<section class="record-form" id="issue"><div class="gw-panel-head"><h2>Issue Equipment</h2><span>Assign an available registered asset.</span></div><form method="post"><input type="hidden" name="action" value="issue_asset"><div class="form-grid"><div><label>Asset</label><select name="asset_id" required><option value="">Select available asset</option><?php foreach($assets as $a): if(($a['status']??'')==='Available' && (int)$a['available_quantity']>0):?><option value="<?=$a['id']?>"><?=e($a['asset_tag'].' — '.$a['name'])?> (<?=e($a['available_quantity'])?> available)</option><?php endif; endforeach;?></select></div><div><label>Employee</label><input name="employee_name" required></div><div><label>Issued Date</label><input type="date" name="issued_date" required value="<?=date('Y-m-d')?>"></div><div><label>Expected Return</label><input type="date" name="expected_return"></div><div class="full"><label>Notes</label><textarea name="notes"></textarea></div></div><div class="record-actions"><button class="gw-btn primary">Issue Equipment</button></div></form></section>
<section class="gw-panel" id="issuance-history" style="margin-top:20px"><div class="gw-panel-head"><h2>Issuance History</h2><span><?=count($issuances)?> records</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Asset</th><th>Employee</th><th>Issued</th><th>Expected Return</th><th>Status</th><th>Notes</th><th>Action</th></tr></thead><tbody><?php foreach($issuances as $r):?><tr><td><?=e($r['asset_tag'].' — '.$r['name'])?></td><td><?=e($r['employee_name'])?></td><td><?=e($r['issued_date'])?></td><td><?=e($r['expected_return'])?></td><td><?=e($r['status'])?></td><td><?=e($r['notes'])?></td><td><form method="post"><input type="hidden" name="action" value="update_issuance_status"><input type="hidden" name="issuance_id" value="<?=$r['id']?>"><select name="status" onchange="this.form.submit()"><option value="Issued" <?=$r['status']==='Issued'?'selected':''?>>Issued</option><option value="Returned" <?=$r['status']==='Returned'?'selected':''?>>Returned</option><option value="Overdue" <?=$r['status']==='Overdue'?'selected':''?>>Overdue</option><option value="Not Returned" <?=$r['status']==='Not Returned'?'selected':''?>>Not Returned</option></select></form></td></tr><?php endforeach;if(!$issuances):?><tr><td colspan="7" class="empty">No issuance records.</td></tr><?php endif;?></tbody></table></div></section><?php page_footer(); ?>
